  "sentences": [
    {
      "text": "FDA's shortage list records Mylan Pharmaceuticals Inc. discontinuing doxycycline hyclate tablets with an initial posting date of 2026-01-12.",
      "cites": ["E10"]
    },
    {
      "text": "FDA's shortage list also records Teva Pharmaceuticals USA, Inc. discontinuing doxycycline hyclate delayed-release tablets with an initial posting date of 2026-07-30.",
      "cites": ["E11"]
    },
    {
      "text": "Our product label names Zydus Lifesciences Limited as the manufacturing plant (FEI 3007938603) with operations including manufacture.",
      "cites": ["E9"]
    },
    {
      "text": "FDA inspection records for this plant show multiple VAI classifications, most recently an inspection ending 2023-03-24 classified VAI.",
      "cites": ["E8", "E9"]
    },
    {
      "text": "No FDA inspection record for this plant shows an OAI classification in the provided evidence.",
      "cites": ["E4", "E5", "E6", "E7", "E8"]
    },
    {
      "text": "Corvale Lakeside holds 19 days on hand, while Corvale East and Corvale General each hold 30 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "Check whether the Zydus plant has any recent inspection actions not captured here and confirm A-S Medication Solutions can supply the needed NDC.",
